tory'::text) OR (\"clientId\" IS NOT NULL)) AND ((kind <> 'staff_goal'::text) OR ((\"staffId\" IS NOT NULL) AND (\"configurationUserId\" IS NOT NULL)))))"},{"name":"C7_measurement_tenant_fk","definition":"FOREIGN KEY (\"tenantId\") REFERENCES \"Tenant\"(id) ON UPDATE RESTRICT ON DELETE RESTRICT"},{"name":"C7_measurement_timezone_ck","definition":"CHECK (((length(timezone) >= 1) AND (length(timezone) <= 100)))"},{"name":"C7_measurement_versions_ck","definition":"CHECK (((revision > 0) AND (\"ruleVersion\" > 0) AND (\"contractVersion\" > 0) AND (\"leaseGeneration\" >= 0)))"},{"name":"MeasurementRevision_pkey","definition":"PRIMARY KEY (id)"}],"indexDefinitions":[{"name":"C7_measurement_attempt_idx","definition":"CREATE INDEX \"C7_measurement_attempt_idx\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"creditedAttemptId\")"},{"name":"C7_measurement_client_idx","definition":"CREATE INDEX \"C7_measurement_client_idx\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"clientId\", kind, \"asOf\")"},{"name":"C7_measurement_execution_idx","definition":"CREATE INDEX \"C7_measurement_execution_idx\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"creditedExecutionId\")"},{"name":"C7_measurement_expiry_idx","definition":"CREATE INDEX \"C7_measurement_expiry_idx\" ON public.\"MeasurementRevision\" USING btree (\"expiresAt\", id)"},{"name":"C7_measurement_generation_uq","definition":"CREATE UNIQUE INDEX \"C7_measurement_generation_uq\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"identityHash\", revision)"},{"name":"C7_measurement_id_tenant_uq","definition":"CREATE UNIQUE INDEX \"C7_measurement_id_tenant_uq\" ON public.\"MeasurementRevision\" USING btree (id, \"tenantId\")"},{"name":"C7_measurement_pending_uq","definition":"CREATE UNIQUE INDEX \"C7_measurement_pending_uq\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"identityHash\") WHERE (state = 'PENDING'::text)"},{"name":"C7_measurement_period_idx","definition":"CREATE INDEX \"C7_measurement_period_idx\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", kind, \"periodFrom\", \"periodTo\")"},{"name":"C7_measurement_request_uq","definition":"CREATE UNIQUE INDEX \"C7_measurement_request_uq\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"requestKeyHash\")"},{"name":"C7_measurement_staff_idx","definition":"CREATE INDEX \"C7_measurement_staff_idx\" ON public.\"MeasurementRevision\" USING btree (\"tenantId\", \"staffId\", kind, \"asOf\")"},{"name":"MeasurementRevision_pkey","definition":"CREATE UNIQUE INDEX \"MeasurementRevision_pkey\" ON public.\"MeasurementRevision\" USING btree (id)"}],"triggerDefinitions":[{"name":"C7_measurement_admission_guard_trg","definition":"CREATE TRIGGER \"C7_measurement_admission_guard_trg\" BEFORE INSERT ON public.\"MeasurementRevision\" FOR EACH ROW EXECUTE FUNCTION \"C7_measurement_admission_guard\"()"},{"name":"C7_measurement_delete_guard_trg","definition":"CREATE TRIGGER \"C7_measurement_delete_guard_trg\" BEFORE DELETE ON public.\"MeasurementRevision\" FOR EACH ROW EXECUTE FUNCTION \"C7_measurement_delete_guard\"()"},{"name":"C7_measurement_publication_guard_trg","definition":"CREATE TRIGGER \"C7_measurement_publication_guard_trg\" BEFORE UPDATE ON public.\"MeasurementRevision\" FOR EACH ROW EXECUTE FUNCTION \"C7_measurement_publication_guard\"()"},{"name":"C7_measurement_truncate_guard_trg","definition":"CREATE TRIGGER \"C7_measurement_truncate_guard_trg\" BEFORE TRUNCATE ON public.\"MeasurementRevision\" FOR EACH STATEMENT EXECUTE FUNCTION \"C7_measurement_truncate_guard\"()"}]};
const hash=s=>crypto.createHash('sha256').update(s).digest('hex');
const db=new PrismaClient({adapter:new PrismaPg({connectionString:process.env.DATABASE_URL})});
(async()=>{
  assert.equal(fs.realpathSync('/opt/maya-saas/current'),'/opt/maya-saas/releases/'+process.env.C7_EXPECTED_RELEASE);
  for(const [path,digest] of Object.entries(expected.artifacts)) assert.equal(hash(fs.readFileSync(path)),digest,path);
  const result=await db.$transaction(async tx=>{
    await tx.$executeRawUnsafe('SET TRANSACTION READ ONLY');
    const columns=await tx.$queryRawUnsafe(`SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='MeasurementRevision' ORDER BY ordinal_position`);
    assert.deepEqual(columns.map(c=>c.column_name),expected.columns);
    const constraints=await tx.$queryRawUnsafe(`SELECT contype::text AS type,confdeltype::text AS deletion,confupdtype::text AS update FROM pg_constraint WHERE conrelid='"MeasurementRevision"'::regclass`);
    assert.equal(constraints.filter(c=>c.type==='c').length,16);
    assert.equal(constraints.filter(c=>c.type==='f'&&c.deletion==='r'&&c.update==='r').length,8);
    const [sourceFK]=await tx.$queryRawUnsafe(`SELECT pg_get_constraintdef(oid) AS definition FROM pg_constraint WHERE conname='C7_measurement_appointment_fk' AND conrelid='"MeasurementRevision"'::regclass`);
    assert.ok(sourceFK.definition.includes('FOREIGN KEY ("appointmentId", "tenantId") REFERENCES "Appointment"(id, "tenantId")'));
    assert.ok(!sourceFK.definition.includes('mayaClientId'));
    const triggers=await tx.$queryRawUnsafe(`SELECT tgname FROM pg_trigger WHERE tgrelid='"MeasurementRevision"'::regclass AND NOT tgisinternal`); assert.equal(triggers.length,4);
    const functions=await tx.$queryRawUnsafe(`SELECT proname,prosrc FROM pg_proc JOIN pg_namespace n ON n.oid=pronamespace WHERE n.nspname='public' AND proname LIKE 'C7_measurement_%'`);
    assert.equal(functions.length,4); for(const f of functions) assert.equal(hash(f.prosrc.trim()),expected.functions[f.proname],f.proname);
    const [constraintDefinitionsResult]=await tx.$queryRawUnsafe(`SELECT coalesce(json_agg(q),'[]') FROM (SELECT conname AS name,pg_get_constraintdef(oid) AS definition FROM pg_constraint WHERE conrelid='"MeasurementRevision"'::regclass ORDER BY conname) q`); assert.deepEqual(constraintDefinitionsResult.coalesce,expected.constraintDefinitions);
    const [indexDefinitionsResult]=await tx.$queryRawUnsafe(`SELECT coalesce(json_agg(q),'[]') FROM (SELECT indexname AS name,indexdef AS definition FROM pg_indexes WHERE schemaname='public' AND tablename='MeasurementRevision' ORDER BY indexname) q`); assert.deepEqual(indexDefinitionsResult.coalesce,expected.indexDefinitions);
    const [triggerDefinitionsResult]=await tx.$queryRawUnsafe(`SELECT coalesce(json_agg(q),'[]') FROM (SELECT tgname AS name,pg_get_triggerdef(oid) AS definition FROM pg_trigger WHERE tgrelid='"MeasurementRevision"'::regclass AND NOT tgisinternal ORDER BY tgname) q`); assert.deepEqual(triggerDefinitionsResult.coalesce,expected.triggerDefinitions);
    const [rows]=await tx.$queryRawUnsafe('SELECT count(*)::text AS n FROM "MeasurementRevision"');
    const migrations=await tx.$queryRawUnsafe(`SELECT migration_name FROM _prisma_migrations WHERE migration_name='20260908153000_chapter7_measurement_foundation' AND finished_at IS NOT NULL AND rolled_back_at IS NULL`); assert.equal(migrations.length,1);
    return {columns:columns.length,checks:16,restrictiveForeignKeys:8,triggers:triggers.length,guardBodiesMatch:true,measurementRows:rows.n,backfillPerformed:false};
  });
  require('reflect-metadata');
  const {MeasurementController}=require('./dist/src/measurement/measurement.controller.js');
  const {TenantAuditReadController}=require('./dist/src/audit-log/tenant-audit-read.controller.js');
  for (const C of [MeasurementController,TenantAuditReadController]) {
    assert.equal(Reflect.getMetadata('tenantScope',C).requireTenant,true);
    assert.equal(Reflect.getMetadata('isPublic',C),undefined);
    assert.equal(Reflect.getMetadata('method',C.prototype.read),0);
  }
  assert.deepEqual(Reflect.getMetadata('roles',TenantAuditReadController),['tenant_owner','business_owner']);
  assert.equal(Reflect.getMetadata('path',MeasurementController),'analytics/measurements');
  assert.equal(Reflect.getMetadata('path',TenantAuditReadController),'audit');
  const policy=require('./dist/src/package5-wave6/package5-wave6.policy.js').WAVE6_CLASSES.expire_measurement_revisions;
  assert.equal(policy.table,'MeasurementRevision'); assert.equal(policy.policyKey,'chapter7.measurement-retention');
  console.log(JSON.stringify({status:'PASS',release:process.env.C7_EXPECTED_RELEASE,...result,artifactsMatched:Object.keys(expected.artifacts).length,businessProviderMessageProofEffects:0},null,2));
})().catch(e=>{console.error(e.message);process.exitCode=1}).finally(()=>db.$disconnect());

NODE
node dist/scripts/release-preflight.js
node node_modules/prisma/build/index.js migrate diff --from-config-datasource --to-schema prisma/schema.prisma --exit-code
curl --fail --silent http://127.0.0.1:3107/api/health
curl --fail --silent http://127.0.0.1:3107/api/health/ready

for route in analytics/measurements audit; do
  code=$(curl --silent --output /dev/null --write-out '%{http_code}' "http://127.0.0.1:3107/api/$route")
  test "$code" = 401
  printf 'UNAUTHENTICATED READ %s: %s\n' "$route" "$code"
done
